/// Node spans and rule ids are recorded (`@schema` or `--spans`).
pub const nodeStore = false;
/// Element extents are kept for side-band labels and nested nodes.
const elemEnds = false;
/// Lists keep trailing nils: positions are fixed by the schema.
const keepTrailingNils = false;
const hasTrivia = false;
const hasRepair = false;
const numSymbols = 96;
const endSymbol: u16 = 1;
const errorSymbol: u16 = 2;

fn tokenToSymbol(self: *BaseParser, token: Token) u16 {
    return switch (token.cat) {
        .@"eof" => 1,
        .@"ident" => identToSymbol(self, token),
        .@"semi" => 38,
        .@"and_and" => 39,
        .@"or_or" => 40,
        .@"amp" => 41,
        .@"pipe" => 44,
        .@"lparen" => 45,
        .@"rparen" => 46,
        .@"lbrace" => 47,
        .@"rbrace" => 48,
        .@"name_eq" => 54,
        .@"lbracket" => 55,
        .@"rbracket" => 56,
        .@"integer" => 59,
        .@"string_sq" => 60,
        .@"string_dq" => 61,
        .@"variable" => 62,
        .@"var_braced" => 63,
        .@"dollar_paren" => 64,
        .@"at_paren" => 65,
        .@"proc_sub_in" => 66,
        .@"proc_sub_out" => 67,
        .@"assign" => 68,
        .@"indent" => 71,
        .@"outdent" => 72,
        .@"str_open" => 79,
        .@"str_body" => 80,
        .@"lt" => 82,
        .@"fd_lt" => 83,
        .@"gt" => 84,
        .@"fd_gt" => 85,
        .@"gt_gt" => 86,
        .@"amp_gt" => 87,
        .@"amp_gt_gt" => 88,
        .@"fd_dup_out" => 89,
        .@"fd_dup_in" => 90,
        .@"heredoc_open" => 91,
        .@"heredoc_body" => 92,
        .@"heredoc_open_lit" => 93,
        else => 2, // error
    };
}

fn identToSymbol(self: *BaseParser, token: Token) u16 {
    const text = self.source[token.pos..][0..token.len];
    if (text.len == 0) return symIdent;
    if (tryIdentAsKeyword(self, text)) |sym| return sym;
    return symIdent;
}

fn tryIdentAsKeyword(self: *BaseParser, text: []const u8) ?u16 {
    const state = self.stateStack.getLast();
    const id = slash.keywordAs(text) orelse return null;
    const idIdx = @intFromEnum(id);
    const sym = keywordToSymbol[idIdx];
    if (sym != 0 and getAction(state, sym) != 0) {
        self.lastMatchedId = @intCast(idIdx);
        return sym;
    }
    const fallback = keywordFallbackSymbol;
    if (fallback != 0 and getAction(state, fallback) != 0) {
        self.lastMatchedId = @intCast(idIdx);
        return fallback;
    }
    return null;
}

